/// Channel to join automatically on every future connect. `None` clears it.
Future<void> setDefaultChannel({required String serverId, String? channel}) =>
    RustLib.instance.api.crateApiMumblewaySetDefaultChannel(
      serverId: serverId,
      channel: channel,
    );

